// warehouse-map · общие помощники (только чтение карты).
import { expect, Page } from '@playwright/test';
import * as path from 'path';

export const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);

/** Сайдбар «האחסון במחסן» / «תכולת …». */
export const side = (page: Page) =>
  page.getByRole('complementary').filter({ has: page.getByRole('button', { name: 'כיווץ סרגל האחסון' }) });

export async function openMap(page: Page, floor?: string) {
  await page.goto('/warehouse/map');
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByRole('tablist', { name: 'קומות המחסן' })).toBeVisible({ timeout: 30_000 });
  if (floor) {
    await page.getByRole('tablist', { name: 'קומות המחסן' }).getByRole('tab', { name: floor }).click();
    await expect(side(page).getByText(floor, { exact: true }).first()).toBeVisible();
  }
}

/**
 * Сетевой guard: карта — реальная раскладка клиента. Любая запись в Supabase (кроме auth и read-RPC)
 * абортируется и запоминается; тест в конце проверяет, что записей не было.
 */
export async function guardWrites(page: Page, extraAllowed: RegExp[] = []) {
  const violations: string[] = [];
  await page.route(/supabase\.co\//, async (route) => {
    const r = route.request();
    const m = r.method();
    const u = r.url();
    const ok =
      ['GET', 'HEAD', 'OPTIONS'].includes(m) ||
      /\/auth\/v1\//.test(u) ||
      /\/rpc\/(movement_journal|inventory_overview)/.test(u) ||
      extraAllowed.some((re) => re.test(u));
    if (ok) return route.continue();
    violations.push(`${m} ${u}`);
    return route.abort();
  });
  return violations;
}

export async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

export async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
}
